basic_top_word:
def solution(words: list[str]) -> str:
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return min(counts, key=lambda word: (-counts[word], word))

basic_accuracy:
def solution(preds: list[int], labels: list[int]) -> float:
    if not preds:
        return 0.0
    same = sum(1 for p, l in zip(preds, labels) if p == l)
    return round(same / len(preds), 2)

applied_top_k_words:
def solution(words: list[str], k: int) -> list[str]:
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return sorted(counts, key=lambda word: (-counts[word], word))[:k]

applied_chunk_tokens:
def solution(tokens: list[int], size: int, overlap: int) -> list[list[int]]:
    chunks = []
    start = 0
    while start < len(tokens):
        chunks.append(tokens[start:start + size])
        if start + size >= len(tokens):
            break
        start += size - overlap
    return chunks

applied_merge_intervals:
def solution(intervals: list[list[int]]) -> list[list[int]]:
    merged = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

applied_longest_unique:
def solution(text: str) -> int:
    last = {}
    start = 0
    best = 0
    for i, ch in enumerate(text):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        best = max(best, i - start + 1)
    return best
